# Allowed classes from the task description
allowed_classes = {'O', 'J', 'F', 'C', 'R', 'H', 'G', 'V', 'X', 'E', 'U', 'K', 'S', 'T', 'A', 'Y', 'P', 'Q', 'L', 'W', 'I', 'N', 'M', 'Z'}

# Reset state for taking items
current_weight = 0
taken_items = []

# Filter items by allowed class and weight capacity
valid_candidates = []
for item_id, props in inspected_items.items():
    if props['class'] in allowed_classes and props['weight'] <= CAPACITY:
        valid_candidates.append({
            'id': item_id,
            'weight': props['weight'],
            'value': props['value'],
            'ratio': props['value'] / props['weight']
        })

# Sort by ratio descending
valid_candidates.sort(key=lambda x: x['ratio'], reverse=True)

# Select items
for item in valid_candidates:
    if current_weight + item['weight'] <= CAPACITY:
        try:
            take_item(item['id'])
            current_weight += item['weight']
            taken_items.append(item['id'])
            print(f"Took {item['id']} (Class {inspected_items[item['id']]['class']}): weight {item['weight']}, value {item['value']}. Total weight: {current_weight}")
        except Exception as e:
            print(f"Failed to take {item['id']}: {e}")

print(f"Final Weight: {current_weight}/{CAPACITY}")
print(f"Total Value: {sum(inspected_items[i]['value'] for i in taken_items)}")

finish()
